const PUSHOVER_ENABLED = false;
const PUSHOVER_RETRY = 300;
const PUSHOVER_EXPIRE = 10800;
const ALLOWED_DASHBOARD_ORIGIN = '';
const ALLOWED_ALERTNAMES = [
  'UniFi update pending over 24h',
  'UniFi update pending over 7 days',
  'pfSense update pending over 24h',
  'pfSense update pending over 7 days',
  'pfSense SECURITY update pending',
  'pfSense update check failing or stale',
  'UniFi poller data stale',
  'Twingate Connector behind over 7 days',
  'Twingate Connector behind over 14 days',
  'Twingate Connector (operator) behind over 14 days',
  'Twingate update check failing or stale',
  'Twingate Connector not ALIVE',
  'Twingate unexpected Connector',
  'Synology DSM update pending over 24h',
  'Synology DSM update pending over 7 days',
  'Synology update data stale',
  'Synology DSM update check failing',
  'Host apt package lists stale',
  'Host update check failing or stale'
];
// PUSHOVER_ENABLED: set to true to send to Pushover. Retry is the seconds
// between repeats of an emergency message (minimum 30). Expire is when repeats
// stop (maximum 10800). ALLOWED_DASHBOARD_ORIGIN: only an https link on exactly
// this origin is forwarded; the empty default drops every link. Example:
// 'https://grafana.example.com'. ALLOWED_ALERTNAMES: only these alert names can
// page at emergency priority or cancel repeats; keep it equal to the titles in
// docker/grafana/provisioning/alerting/update-alert-rules-*.yml.
// No Pushover credential is handled here: the HTTP Request nodes add them from
// the n8n credential pushover-api.

const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const str = (v, max) => {
  if (typeof v === 'string') { return v.slice(0, max); }
  if (typeof v === 'number' && isFinite(v)) { return String(v).slice(0, max); }
  return '';
};

function sha256hex(s) {
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  const primes = [];
  for (let n = 2; primes.length < 64; n++) {
    let ok = true;
    for (let d = 2; d * d <= n; d++) { if (n % d === 0) { ok = false; break; } }
    if (ok) { primes.push(n); }
  }
  const K = primes.map((p) => Math.floor((Math.cbrt(p) % 1) * 4294967296));
  let H = primes.slice(0, 8).map((p) => Math.floor((Math.sqrt(p) % 1) * 4294967296));
  const m = [];
  for (let i = 0; i < s.length; i++) { m.push(s.charCodeAt(i) & 255); }
  const bits = m.length * 8;
  m.push(0x80);
  while (m.length % 64 !== 56) { m.push(0); }
  m.push(0, 0, 0, 0, (bits >>> 24) & 255, (bits >>> 16) & 255, (bits >>> 8) & 255, bits & 255);
  for (let o = 0; o < m.length; o += 64) {
    const w = new Array(64);
    for (let t = 0; t < 16; t++) {
      w[t] = (m[o + 4 * t] << 24) | (m[o + 4 * t + 1] << 16) | (m[o + 4 * t + 2] << 8) | m[o + 4 * t + 3];
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[t] + w[t]) | 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    const v = [a, b, c, d, e, f, g, h];
    H = H.map((x, i) => (x + v[i]) | 0);
  }
  return H.map((x) => ('00000000' + (x >>> 0).toString(16)).slice(-8)).join('');
}

function safeDashboardUrl(u) {
  if (!ALLOWED_DASHBOARD_ORIGIN || typeof u !== 'string' || u.length > 512) { return ''; }
  if (/[\\\u0000-\u001f\u007f]/.test(u)) { return ''; }
  let allowed;
  let p;
  try { allowed = new URL(ALLOWED_DASHBOARD_ORIGIN); p = new URL(u); } catch (e) { return ''; }
  if (allowed.protocol !== 'https:') { return ''; }
  if (p.protocol !== 'https:' || p.username || p.password) { return ''; }
  if (p.origin !== allowed.origin) { return ''; }
  return p.href.length > 512 ? '' : p.href;
}

function build() {
  const raw = $('Normalize Alert').first().json.body;
  if (!isObj(raw)) { throw new Error('body'); }
  if (raw.status !== 'firing' && raw.status !== 'resolved') { throw new Error('status'); }
  if (!Array.isArray(raw.alerts) || raw.alerts.length < 1) { throw new Error('alerts'); }
  const a = raw.alerts[0];
  if (!isObj(a)) { throw new Error('alert'); }
  const l = a.labels === undefined ? {} : a.labels;
  const an = a.annotations === undefined ? {} : a.annotations;
  if (!isObj(l) || !isObj(an)) { throw new Error('maps'); }
  const resolved = raw.status === 'resolved';
  // The phone label is the only way an alert reaches Pushover (everything else
  // stays on Discord). The malformed-alert notice in the catch below is exempt.
  const phone = str(l.phone, 10) === 'true';
  const alertname = str(l.alertname, 200);
  const known = ALLOWED_ALERTNAMES.indexOf(alertname) !== -1;
  const severity = str(l.severity, 20);
  const urgent = severity === 'critical' || str(l.update_security, 10) === 'true';
  let prio = 0;
  if (!resolved) {
    if (known && urgent) { prio = 2; } else if (urgent || severity === 'warning') { prio = 1; }
  }
  const title = ((resolved ? 'RESOLVED: ' : '') + (alertname || 'Grafana alert')).slice(0, 250);
  const summary = str(an.summary, 300) || ('Alert condition ' + (resolved ? 'cleared' : 'is true'));
  const description = str(an.description, 600);
  const msg = (summary + (description ? '\n' + description : '')
    + (raw.alerts.length > 1 ? '\n(+' + (raw.alerts.length - 1) + ' more alerts)' : '')).slice(0, 1024);
  const fingerprint = str(a.fingerprint, 64);
  const tag = (known && /^[0-9a-fA-F]{1,64}$/.test(fingerprint))
    ? 'upd-' + sha256hex(alertname + '|' + fingerprint).slice(0, 32) : '';
  const o = { title: title, message: msg, priority: prio };
  if (prio === 2) {
    o.retry = Math.max(30, Math.floor(Number(PUSHOVER_RETRY)) || 300);
    o.expire = Math.min(10800, Math.floor(Number(PUSHOVER_EXPIRE)) || 10800);
    if (tag) { o.tags = tag; }
  }
  const url = safeDashboardUrl(a.dashboardURL);
  if (url) { o.url = url; }
  return { enabled: PUSHOVER_ENABLED === true && phone, pushover: o, cancelTag: resolved ? tag : '' };
}

let out;
try {
  out = build();
} catch (e) {
  out = {
    enabled: PUSHOVER_ENABLED === true,
    pushover: {
      title: 'Alert router: malformed alert',
      message: 'The router received a malformed alert from the webhook. Check the sender and the n8n execution log.',
      priority: 1,
    },
    cancelTag: '',
  };
}
return [{ json: out }];

// Runs directly behind the webhook. It builds a NEW body that is safe for every
// downstream expression: scalars are coerced to capped strings, objects and
// arrays in scalar positions are dropped, and labels and annotations are fresh
// plain objects. A body the router cannot route safely becomes
// {status: 'malformed'}, which the Alert Status switch sends to the
// malformed-alert notifications. This node never throws, so an authenticated
// call cannot end in silence. The Discord and Pushover nodes read only the
// fields built here (a test scans their expressions to keep it that way).
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const s = (v, max) => {
  if (typeof v === 'string') { return v.slice(0, max); }
  if (typeof v === 'number' && isFinite(v)) { return String(v).slice(0, max); }
  if (typeof v === 'boolean') { return String(v); }
  return '';
};
const ts = (v) => {
  const t = s(v, 64);
  return t && !isNaN(Date.parse(t)) ? t : '';
};
const ANNOTATIONS = { summary: 300, description: 1000, trigger_logic: 300, trigger_query: 300, threshold: 100, window: 100 };

function clean(a) {
  const l = isObj(a.labels) ? a.labels : {};
  const an = isObj(a.annotations) ? a.annotations : {};
  const labels = {};
  Object.keys(l).slice(0, 50).forEach((k) => {
    if (k !== '__proto__') { labels[k.slice(0, 100)] = s(l[k], 200); }
  });
  const annotations = {};
  Object.keys(ANNOTATIONS).forEach((k) => { annotations[k] = s(an[k], ANNOTATIONS[k]); });
  return {
    labels: labels,
    annotations: annotations,
    valueString: s(a.valueString, 300),
    startsAt: ts(a.startsAt),
    endsAt: ts(a.endsAt),
    dashboardURL: s(a.dashboardURL, 512),
    panelURL: s(a.panelURL, 512),
    generatorURL: s(a.generatorURL, 512),
    fingerprint: s(a.fingerprint, 64),
  };
}

let out = { body: { status: 'malformed', alerts: [] } };
try {
  const item = $input.first().json;
  const b = isObj(item) ? item.body : undefined;
  const ok = isObj(b)
    && (b.status === 'firing' || b.status === 'resolved')
    && Array.isArray(b.alerts) && b.alerts.length >= 1 && isObj(b.alerts[0])
    && (b.alerts[0].labels === undefined || isObj(b.alerts[0].labels))
    && (b.alerts[0].annotations === undefined || isObj(b.alerts[0].annotations));
  if (ok) {
    const alerts = [clean(b.alerts[0])];
    for (let i = 1; i < Math.min(b.alerts.length, 1000); i++) { alerts.push({}); }
    out = { body: { status: b.status, alerts: alerts } };
  }
} catch (e) {
  out = { body: { status: 'malformed', alerts: [] } };
}
return [{ json: out }];

// Builds the heartbeat ping for the alert-path dead-man's switch (issue #80).
// The sink is a setting, read from the n8n container environment: HEARTBEAT_PING_URL
// (the observer's ping URL, treated as a secret) and optional HEARTBEAT_KIND
// ('healthchecks' by default, or 'uptimekuma'). With no valid URL the feature is
// off: no ping and no error. n8n must allow env access in nodes
// (N8N_BLOCK_ENV_ACCESS_IN_NODE=false); when it blocks it, the feature stays off.
// This node never throws, never logs, and never copies alert content into the
// request: the output is only {send, url}. A ping that fails is handled by the
// HTTP Request node (continue on error), so it cannot fail a real alert.
//   healthchecks: GET <base>        = all is well
//                 GET <base>/fail   = the heartbeat broke its contract
//   uptimekuma:   GET <push>?status=up&msg=OK
//                 GET <push>?status=down&msg=...
// Contract: status firing, label heartbeat=true and label phone=false. A resolved
// heartbeat (the rule was paused or removed) sends nothing, so the observer's own
// timeout does the alerting.
const MAX_URL = 512;
let out = { send: false };
try {
  let rawUrl = '';
  let rawKind = '';
  try {
    rawUrl = $env.HEARTBEAT_PING_URL;
    rawKind = $env.HEARTBEAT_KIND;
  } catch (e) {
    rawUrl = '';
  }
  const kind = (typeof rawKind === 'string' && rawKind.trim() !== '') ? rawKind.trim().toLowerCase() : 'healthchecks';
  const url = typeof rawUrl === 'string' ? rawUrl.trim() : '';
  const shapeOk = url.length > 0 && url.length <= MAX_URL
    && /^https?:\/\/[^\s\/?#@]+(?:[\/?#]\S*)?$/.test(url)
    && !/[\u0000-\u001f\u007f]/.test(url);
  if (shapeOk && (kind === 'healthchecks' || kind === 'uptimekuma')) {
    const item = $input.first().json;
    const body = item && typeof item === 'object' ? item.body : null;
    const alerts = body && Array.isArray(body.alerts) ? body.alerts : [];
    const first = alerts[0] && typeof alerts[0] === 'object' ? alerts[0] : {};
    const labels = first.labels && typeof first.labels === 'object' ? first.labels : {};
    const status = body && typeof body.status === 'string' ? body.status : '';
    if (status === 'firing') {
      const good = labels.heartbeat === 'true' && labels.phone === 'false';
      const noFragment = url.split('#')[0];
      const base = noFragment.split('?')[0].replace(/\/+$/, '');
      if (kind === 'healthchecks') {
        out = { send: true, url: good ? base : base + '/fail' };
      } else {
        out = { send: true, url: base + (good ? '?status=up&msg=OK' : '?status=down&msg=heartbeat%20contract%20failed') };
      }
    }
  }
} catch (e) {
  out = { send: false };
}
return [{ json: out }];

// Entry check for the expiry watch (issues #127, #128). The expiry watch posts to its own
// endpoint, the Expiry Watch Webhook, and proves itself with the header
//   Authorization: Bearer <value of EXPIRY_WATCH_ROUTER_SECRET>
// The secret is read from the n8n container environment (n8n must allow env access in
// nodes: N8N_BLOCK_ENV_ACCESS_IN_NODE=false, as the heartbeat already needs). Grafana
// does not come through here: it keeps n8n Header Auth on its own webhook.
// Two jobs, both fail closed (any problem answers 403 and routes nothing):
// 1. Authenticate. An unset, blank, non-text or unreadable variable, a missing,
//    non-text or oversized header, or any difference denies the call. An empty value
//    never matches an empty header. The comparison visits every position and ORs the
//    differences, so its time does not depend on where the first difference is.
// 2. Authorize. The secret only proves the caller is the expiry watch, so the body may
//    only be an expiry notice in exactly the shape scripts/expiry_watch.py builds. It is
//    checked field by field (unknown keys are refused, not passed on), and a NEW body is
//    built from the checked fields with the source label set to expiry-watch. A body that
//    claims a Grafana alert name, a heartbeat, update_security, a resolved status, URLs,
//    more than one alert or any other label is denied, so this credential cannot page or
//    cancel as Grafana. The expiry alert name prefix is not on the Pushover builder's alert name allowlist, so
//    these notices stay at Pushover priority 1 at most.
// No text from the caller is displayed: item and kind are limited to a plain character set
// (letters, digits, space, dot, colon, hyphen; no markdown, mention, link or control
// characters), and the summary and description are built here from item, kind and stage.
// Whatever the caller sends in the annotations is dropped.
// The configured secret is capped too (MAX_SECRET), before any loop runs over it.
// Only the new body leaves this node: never the header, never the secret. This node never
// throws and never logs.
const MAX_HEADER = 512;
const MAX_SECRET = 400;
const MAX_BODY = 16384;
const MIN_INTERVAL_MS = 1000;
const WINDOW_MS = 600000;
const MAX_PER_WINDOW = 30;
const isStr = (v) => typeof v === 'string';
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const only = (o, keys) => Object.keys(o).every((k) => keys.indexOf(k) !== -1);
const text = (v, min, max) => isStr(v) && v.length >= min && v.length <= max;
const NAME_PREFIX = 'Expiry watch: ';
const DESCRIPTION = 'Generated by the alert router from the expiry watch notice. See the expiry watch output and the runbook.';

// Size limit (issue #157): the watch posts over loopback, so no proxy caps the body. Content-Length, when n8n
// passes it on, must be a plain number within the cap; the parsed body re-serialized must fit too. A body
// that cannot be measured is denied. The raw bytes are not visible to a Code node, so this is a check of the
// parsed body (UNVERIFIED against a live n8n whether the content-length header is passed on).
function withinSize(item) {
  const h = item.headers && typeof item.headers === 'object' ? item.headers['content-length'] : undefined;
  if (h !== undefined && (!isStr(h) || !/^[0-9]{1,9}$/.test(h) || Number(h) > MAX_BODY)) { return false; }
  const s = JSON.stringify(item.body);
  if (!isStr(s)) { return false; }
  let bytes = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c < 0x80) { bytes += 1; }
    else if (c < 0x800) { bytes += 2; }
    else if (c >= 0xD800 && c <= 0xDBFF) { bytes += 4; i++; }
    else { bytes += 3; }
    if (bytes > MAX_BODY) { return false; }
  }
  return true;
}

// Rate limit (issue #157): at least MIN_INTERVAL_MS between accepted calls and at most MAX_PER_WINDOW accepted
// calls per WINDOW_MS, kept in the workflow static data. Only a call that already passed the secret and the
// shape check is counted, so a caller without the secret cannot use up the watch's allowance. Fails closed when
// the static data cannot be read. UNVERIFIED against a live n8n: static data is saved when a production
// execution ends, and two executions that overlap may both read the old value.
function underRate(now) {
  const sd = $getWorkflowStaticData('global');
  const recent = Array.isArray(sd.expiryWatchRecent)
    ? sd.expiryWatchRecent.filter((t) => typeof t === 'number' && t <= now && t > now - WINDOW_MS) : [];
  if (recent.length >= MAX_PER_WINDOW) { return false; }
  if (recent.length > 0 && now - recent[recent.length - 1] < MIN_INTERVAL_MS) { return false; }
  recent.push(now);
  sd.expiryWatchRecent = recent;
  return true;
}

function summaryFor(item, kind, stage) {
  let what;
  if (stage === 'expired') { what = 'has expired'; }
  else if (stage === 'disappeared') { what = 'is no longer listed by its provider'; }
  else if (stage === 'daily') { what = 'is expiring soon, daily reminder'; }
  else { what = 'expires within ' + stage + ' days'; }
  return item + ' (' + kind + '): ' + what;
}

function expiryBody(b) {
  if (!isObj(b) || !only(b, ['receiver', 'status', 'alerts'])) { return null; }
  if (b.status !== 'firing' || (b.receiver !== undefined && b.receiver !== 'expiry-watch')) { return null; }
  if (!Array.isArray(b.alerts) || b.alerts.length !== 1 || !isObj(b.alerts[0])) { return null; }
  const a = b.alerts[0];
  if (!only(a, ['status', 'labels', 'annotations', 'startsAt', 'fingerprint'])) { return null; }
  if (a.status !== undefined && a.status !== 'firing') { return null; }
  const l = a.labels;
  const an = a.annotations;
  if (!isObj(l) || !isObj(an)) { return null; }
  if (!only(l, ['alertname', 'severity', 'expiry_watch', 'item', 'kind', 'stage', 'phone'])) { return null; }
  if (!only(an, ['summary', 'description'])) { return null; }
  if (!isStr(l.item) || !/^[A-Za-z0-9][A-Za-z0-9 .:-]{0,99}$/.test(l.item)) { return null; }
  if (!isStr(l.kind) || !/^[A-Za-z0-9][A-Za-z0-9-]{0,39}$/.test(l.kind)) { return null; }
  if (l.alertname !== (NAME_PREFIX + l.item).slice(0, 200)) { return null; }
  if (l.severity !== 'critical' && l.severity !== 'warning' && l.severity !== 'info') { return null; }
  if (l.expiry_watch !== 'true') { return null; }
  if (!isStr(l.stage) || !/^(?:[0-9]{1,4}|daily|expired|disappeared)$/.test(l.stage)) { return null; }
  if (l.phone !== undefined && l.phone !== 'true') { return null; }
  if (an.summary !== undefined && !text(an.summary, 0, 300)) { return null; }
  if (an.description !== undefined && !text(an.description, 0, 1000)) { return null; }
  if (!isStr(a.fingerprint) || !/^[0-9a-f]{32}$/.test(a.fingerprint)) { return null; }
  if (a.startsAt !== undefined && (!isStr(a.startsAt) || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$/.test(a.startsAt))) { return null; }
  const labels = { alertname: l.alertname, severity: l.severity, expiry_watch: 'true', item: l.item, kind: l.kind, stage: l.stage };
  if (l.phone === 'true') { labels.phone = 'true'; }
  labels.source = 'expiry-watch';
  const annotations = { summary: summaryFor(l.item, l.kind, l.stage), description: DESCRIPTION };
  const alert = { labels: labels, annotations: annotations, fingerprint: a.fingerprint };
  if (a.startsAt !== undefined) { alert.startsAt = a.startsAt; }
  return { status: 'firing', alerts: [alert] };
}

let out = { authorized: false };
try {
  let cfg = '';
  try {
    cfg = $env.EXPIRY_WATCH_ROUTER_SECRET;
  } catch (e) {
    cfg = '';
  }
  const item = $input.first().json;
  const headers = item && typeof item === 'object' && item.headers && typeof item.headers === 'object' ? item.headers : {};
  const hdr = headers.authorization;
  if (isStr(cfg) && cfg.trim() !== '' && cfg.length <= MAX_SECRET && isStr(hdr) && hdr.length <= MAX_HEADER) {
    const expected = 'Bearer ' + cfg;
    let diff = expected.length ^ hdr.length;
    const n = Math.max(expected.length, hdr.length);
    for (let i = 0; i < n; i++) {
      diff |= (expected.charCodeAt(i) || 0) ^ (hdr.charCodeAt(i) || 0);
    }
    if (diff === 0 && withinSize(item)) {
      const body = expiryBody(item.body);
      if (body !== null && underRate(Date.now())) {
        out = { authorized: true, body: body };
      }
    }
  }
} catch (e) {
  out = { authorized: false };
}
return [{ json: out }];
